fn is_palindrome(v: &Vec[Int]) -> Bool {
  var left = 0;
  var right = v.len() - 1;
  while left < right {
    if v[left] != v[right] {
      return false;
    }
    left = left + 1;
    right = right - 1;
  }
  return true;
}

fn remove_last(v: &mut Vec[Int]) -> Int {
  if v.is_empty() { return -1; }
  match v.pop() {
    Some(n) => { return n; }
    None => { return -1; }
  }
}

fn duplicate_all(v: &mut Vec[Int]) -> Unit {
  var i = 0;
  while i < v.len() {
    v[i] = v[i] * 2;
    i = i + 1;
  }
}

fn main() -> Int {
  var v = Vec[Int]();
  v.push(1); v.push(2); v.push(1);
  if is_palindrome(&v) { return 1; }
  return 0;
}
